// GENERATED by scripts/generate_font_assets.py — do not edit by hand.
// Metrics are extracted from the exact static WOFF2 files under fonts/.
// Every value is normalized to 1000 units/em for deterministic browser layout.
// Each family's tables are a module under metrics/, loaded on demand by
// metrics.ts, which unpacks a face into lookup records on first use.

export type FaceName = "regular" | "bold" | "italic" | "boldItalic" | "boldDisplay" | "caps";
export type MetricFamilyId = "latin-modern" | "source-serif" | "source-sans" | "tinos" | "arimo" | "carlito" | "crimson-pro" | "dm-sans" | "fira-sans" | "ibm-plex-sans" | "ibm-plex-serif" | "inter" | "lato" | "libre-baskerville" | "libre-franklin" | "lora" | "merriweather" | "merriweather-sans" | "montserrat" | "noto-sans" | "noto-serif" | "nunito" | "nunito-sans" | "open-sans" | "pt-sans" | "pt-serif" | "raleway" | "roboto" | "rubik" | "work-sans";

// One face's tables, indexed by position in `glyphs`. The pair kerning for
// glyphs i, j is kern[kernLeft[i] * kernColumns + kernRight[j]], zero meaning
// no pair. ligatureKern keys "left|right" around a ligature; its zeros count.
export type PackedFaceMetrics = {
  ascent: number;
  descent: number;
  capHeight: number;
  xHeight: number;
  glyphs: string;
  adv: number[];
  bbox: Array<[number, number] | 0>;
  lig: Record<string, number>;
  kernLeft: number[];
  kernRight: number[];
  kernColumns: number;
  kern: number[];
  ligatureKern: Record<string, number>;
  // Characters the face draws but leaves unmeasured (mark-class glyphs); they
  // are never borrowed from a fallback family.
  unmeasured?: string;
};

// A face name in place of tables aliases that face's record (FACE_ALIASES).
export type PackedFamilyMetrics = Record<FaceName, PackedFaceMetrics | FaceName>;

// One lazy module per family, so a document ships only the metrics it uses.
